                    end

                    local Adopted = self:RefreshState()

                    if Adopted then
                        local Loaded, LoadError = self:Load(Adopted)

                        if not Loaded then
                            return Rollback(LoadError)
                        end
                    else
                        local Created, CreateError = self:Save('default')

                        if not Created then
                            return Rollback(CreateError)
                        end

                        self:SetAutoload('default')
                    end

                    return true
                end
                function SaveManager:SetIgnoreIndexes(List)
                    for _, Key in List or {}do
                        self.Ignore[Key] = true
                    end

                    return self
                end
                function SaveManager:IgnoreThemeSettings()
                    self.IgnoreTheme = true

                    return self
                end
                function SaveManager:IsIgnored(Index)
                    if self.Ignore[Index] == true or Library:IsSettingsFlag(Index) then
                        return true
                    end

                    local Control = self.Options and self.Options[Index]

                    return Control ~= nil and Control.Locked == true
                end
                function SaveManager:EncodeOption(Index, Option)
                    if Option.Type == 'Toggle' then
                        return {
                            type = 'Toggle',
                            idx = Index,
                            value = Option.Value == true,
                        }
                    elseif Option.Type == 'Slider' then
                        return {
                            type = 'Slider',
                            idx = Index,
                            value = tonumber(Option.Value) or 0,
                        }
                    elseif Option.Type == 'Dropdown' then
                        return {
                            type = 'Dropdown',
                            idx = Index,
                            value = Option.Value,
                            multi = Option.Multi == true,
                            priority = Option.Priority == true,
                        }
                    elseif Option.Type == 'Colorpicker' then
                        local Color = Option.Color or (Option.Get and Option:Get())

                        if typeof(Color) == 'Color3' then
                            return {
                                type = 'Colorpicker',
                                idx = Index,
                                value = Color:ToHex(),
                                transparency = Option.GetAlpha and (1 - Option:GetAlpha()) or nil,
                            }
                        end
                    elseif Option.Type == 'Keybind' then
                        return {
                            type = 'Keybind',
                            idx = Index,
                            value = Option.Get and Option:Get() or Option.Value,
                        }
                    elseif Option.Type == 'Input' then
                        return {
                            type = 'Input',
                            idx = Index,
                            text = tostring(Option.Value or ''),
                        }
                    end

                    return nil
                end
                function SaveManager:ApplyOption(Data)
                    if type(Data) ~= 'table' or type(Data.idx) ~= 'string' then
                        return false
                    end
                    if Library.PendingAutoSaveFlags[Data.idx] then
                        return true
                    end

                    local Option = self.Options[Data.idx]

                    if not Option or not Option.SetValue then
                        return false
                    end
                    if Data.type and Data.type ~= Option.Type then
                        return false
                    end
                    if Option.Type == 'Toggle' and type(Data.value) ~= 'boolean' then
                        return false
                    end
                    if Data.type == 'Colorpicker' then
                        local Success, Color = pcall(Color3.fromHex, tostring(Data.value or ''))

                        if not Success or typeof(Color) ~= 'Color3' then
                            return false
                        end

                        return Option:SetValueRGB(Color, Data.transparency, {FromConfig = true}) ~= false
                    elseif Data.type == 'Keybind' then
                        local Value = Data.value

                        if Value == nil and Data.key ~= nil then
                            Value = {
                                Key = Data.key,
                                Toggled = Data.toggled == true,
                            }
                        end

                        return Option:SetValue(Value, {FromConfig = true}) ~= false
                    elseif Data.type == 'Input' then
                        return type(Data.text) == 'string' and Option:SetValue(Data.text, {FromConfig = true}) ~= false
                    end

                    return Option:SetValue(Data.value, {FromConfig = true}) ~= false
                end
                function SaveManager:Save(Name)
                    if type(writefile) ~= 'function' then
                        return false, 'File APIs unavailable'
                    end

                    Name = Library:NormalizeConfigName(Name)

                    if not Name then
                        return false, 'Invalid config name'
                    end

                    local FolderSuccess, FolderError = self:BuildFolderTree()

                    if not FolderSuccess then
                        return false, FolderError
                    end

                    local SaveRevision = Library.AutoSaveRevision
                    local Objects, Encoded_Indexes = {}, {}

                    for Index, Option in self.Options do
                        if not self:IsIgnored(Index) then
                            local Encoded = self:EncodeOption(Index, Option)

                            if Encoded then
                                Encoded_Indexes[Index] = true

                                TableInsert(Objects, Encoded)
                            end
                        end
                    end
                    for Index, Object in self.PendingObjects do
                        if not Encoded_Indexes[Index] and not self:IsIgnored(Index) then
                            TableInsert(Objects, Object)
                        end
                    end

                    table.sort(Objects, function(First, Second)
                        return tostring(First.idx) < tostring(Second.idx)
                    end)

                    local EncodeSuccess, Encoded = pcall(HttpService.JSONEncode, HttpService, {
                        version = 1,
                        objects = Objects,
                    })

                    if not EncodeSuccess then
                        return false, 'Failed to encode config'
                    end

                    local WriteSuccess, WriteError = pcall(writefile, self:GetConfigPath(Name), Encoded)

                    if not WriteSuccess then
                        return false, tostring(WriteError)
                    end

                    Library.SelectedConfig = Name
                    Library.ActiveConfig = Name

                    if Library.AutoSaveRevision == SaveRevision then
                        Library.AutoSaveDirty = false
                        Library.PendingAutoSaveFlags = {}
                    else
                        Library.AutoSaveDirty = true
                    end

                    Library.AutoSaveRetryCount = 0

                    return true, Name
                end
                function SaveManager:Load(Name, Options)
                    if type(readfile) ~= 'function' or type(isfile) ~= 'function' then
                        return false, 'File APIs unavailable'
                    end

                    Name = Library:NormalizeConfigName(Name)

                    if not Name then
                        return false, 'No config selected'
                    end

                    local Path = self:GetConfigPath(Name)

                    if not isfile(Path) then
                        return false, 'Config not found'
                    end

                    local ReadSuccess, Content = pcall(readfile, Path)

                    if not ReadSuccess then
                        return false, tostring(Content)
                    end

                    local DecodeSuccess, Data = pcall(HttpService.JSONDecode, HttpService, Content)

                    if not DecodeSuccess or type(Data) ~= 'table' or type(Data.objects) ~= 'table' then
                        return false, 'Invalid config data'
                    end
                    if not (Options and Options.PreserveEdits) then
                        Library.PendingAutoSaveFlags = {}
                    end

                    Library.LoadingConfig = true

                    local AppliedCount, ErrorCount, PendingCount = 0, 0, 0
                    local ConfigErrors, Pending = {}, {}
                    local ConfigSliceStarted = os.clock()

                    pcall(function()
                        for _, Object in Data.objects do
                            if type(Object) ~= 'table' or type(Object.idx) ~= 'string' then
                                ErrorCount = ErrorCount + 1

                                TableInsert(ConfigErrors, {
                                    Index = '?',
                                    Type = typeof(Object),
                                    Error = 'malformed config entry',
                                })

                                continue
                            end

                            local Success, Applied = pcall(self.ApplyOption, self, Object)

                            if Success and Applied then
                                AppliedCount = AppliedCount + 1
                            else
                                ErrorCount = ErrorCount + 1

                                if Pending[Object.idx] == nil then
                                    PendingCount = PendingCount + 1
                                end

                                Pending[Object.idx] = Object

                                TableInsert(ConfigErrors, {
                                    Index = tostring(Object.idx),
                                    Type = tostring(Object.type),
                                    Error = Success and 'rejected saved value' or tostring(Applied),
                                })
                            end
                            if Library.CooperativeBuild and os.clock() - ConfigSliceStarted >= Library.CooperativeBuildBudget then
                                task.wait()

                                ConfigSliceStarted = os.clock()
                            end
                        end
                    end)

                    Library.LoadingConfig = false
                    self.PendingObjects = Pending
                    Library.LastConfigErrors = ConfigErrors
                    Library.SelectedConfig = Name
                    Library.ActiveConfig = Name

                    Library:FlushOptionCallbacks()

                    local HasPendingAutoSave = next(Library.PendingAutoSaveFlags) ~= nil

                    Library.AutoSaveDirty = HasPendingAutoSave
                    Library.AutoSaveToken = Library.AutoSaveToken + 1
                    Library.AutoSaveQueued = false
                    Library.AutoSaveRetryCount = 0

                    if HasPendingAutoSave then
                        task.defer(function()
                            if not Library.IsUnloading then
                                Library:QueueAutoSave(nil, true)
                            end
                        end)
                    end

                    return true, Name, AppliedCount, PendingCount, ErrorCount
                end
                function SaveManager:RefreshConfigList()
                    self:BuildFolderTree()

                    if type(listfiles) ~= 'function' then
                        return {}, false
                    end

                    local Success, Files = pcall(listfiles, self:GetFolder())

                    if not Success or type(Files) ~= 'table' then
                        return {}, false
                    end

                    local Names, Seen = {}, {}

                    for _, Path in Files do
                        local Name = Library:NormalizeConfigName(tostring(Path):match('([^/\\]+)%.json$'))

                        if Name and Name ~= 'options' and not Seen[Name] then
                            Seen[Name] = true

                            TableInsert(Names, Name)
                        end
                    end

                    table.sort(Names, function(First, Second)
                        return StringLower(First) < StringLower(Second)
                    end)

                    return Names, true
                end
                function SaveManager:PickFreeConfigName(Base)
                    Base = Library:NormalizeConfigName(Base) or 'recovered'

                    if type(isfile) ~= 'function' then
                        return Base
                    end
                    if not isfile(self:GetConfigPath(Base)) then
                        return Base
                    end

                    for Index = 2, 50 do
                        local Candidate = Base .. tostring(Index)

                        if not isfile(self:GetConfigPath(Candidate)) then
                            return Candidate
                        end
                    end

                    return nil
                end
                function SaveManager:ResetOptionsToDefault()
                    Library.PendingAutoSaveFlags = {}
                    Library.LoadingConfig = true

                    pcall(function()
                        for Index, Option in self.Options do
                            if not self:IsIgnored(Index) and Option.DefaultSnapshot then
                                pcall(self.ApplyOption, self, Option.DefaultSnapshot)
                            end
                        end
                    end)

                    Library.LoadingConfig = false
                    self.PendingObjects = {}

                    Library:FlushOptionCallbacks()

                    return true
                end
                function SaveManager:Delete(Name)
                    Name = Library:NormalizeConfigName(Name)

                    if not Name then
                        return false, 'No config selected'
                    end

                    local WasAutoload = ReadTrimmedFile(self:GetAutoloadPath()) == Name
                    local Path = self:GetConfigPath(Name)

                    if type(isfile) ~= 'function' or not isfile(Path) then
                        return false, 'Config not found'
                    end
                    if type(delfile) ~= 'function' then
                        return false, 'Delete file API unavailable'
                    end

                    local Success, ErrorText = pcall(delfile, Path)

                    if not Success then
                        return false, tostring(ErrorText)
                    end
                    if WasAutoload then
                        ClearFile(self:GetAutoloadPath())
                    end

                    local WasActive = Library.ActiveConfig == Name

                    if WasActive then
                        Library.ActiveConfig = nil
                        Library.AutoSaveDirty = false
                        Library.AutoSaveToken = Library.AutoSaveToken + 1
                        Library.AutoSaveQueued = false
                        Library.PendingAutoSaveFlags = {}
                        self.PendingObjects = {}
                    end
                    if Library.SelectedConfig == Name then
                        Library.SelectedConfig = nil
                    end

                    local Configs, Enumerated = self:RefreshConfigList()
                    local RecreateError

                    if Enumerated and #Configs == 0 then
                        self:ResetOptionsToDefault()

                        local Created, NameOrError = self:Save('default')

                        if Created then
                            Configs = {NameOrError}
                        else
                            RecreateError = NameOrError
                        end
                    end

                    local Adopted = self:RefreshState()

                    if Adopted and not Library.ActiveConfig then
                        self.AutoloadLoaded = false

                        local Loaded, LoadError = self:Load(Adopted)

                        if not Loaded then
                            pcall(Library.Notify, Library, {
                                Title = 'Config load failed',
                                Content = tostring(LoadError),
                                Duration = 4,
                            })

                            return true, Name, LoadError
                        end
                    end
                    if not Library.ActiveConfig and RecreateError then
                        return false, RecreateError
                    end

                    return true, Name
                end
                function SaveManager:SetAutoload(Name)
                    if type(writefile) ~= 'function' then
                        return false, 'File APIs unavailable'
                    end

                    local FolderSuccess, FolderError = self:BuildFolderTree()

                    if not FolderSuccess then
                        return false, FolderError
                    end
                    if Name == nil then
                        return false, 'Autoload cannot be disabled; pass a config name'
                    end

                    Name = Library:NormalizeConfigName(Name)

                    if not Name then
                        return false, 'Invalid config name'
                    end
                    if not self:ConfigExists(Name) then
                        return false, 'Save or select a config first'
                    end

                    local Success, ErrorText = pcall(writefile, self:GetAutoloadPath(), Name)

                    if not Success then
                        return false, tostring(ErrorText)
                    end

                    Library.AutoLoadConfig = Name
                    Library.SelectedConfig = Name
                    self.AutoloadLoaded = false

                    return true, Name
                end
                function SaveManager:RefreshState()
                    local Configs, Enumerated = self:RefreshConfigList()
                    local Stored = ReadTrimmedFile(self:GetAutoloadPath())

                    Stored = Stored and Library:NormalizeConfigName(Stored) or nil

                    local Autoload = (self:ConfigExists(Stored) and Stored) or (self:ConfigExists('default') and 'default') or Configs[1] or nil

                    if Autoload ~= Stored then
                        if Autoload and type(writefile) == 'function' then
                            pcall(writefile, self:GetAutoloadPath(), Autoload)
                        elseif not Autoload and Enumerated then
                            ClearFile(self:GetAutoloadPath())
                        end
                    end

                    Library.AutoLoadConfig = Autoload

                    if not Library.SelectedConfig or not self:ConfigExists(Library.SelectedConfig) then
                        Library.SelectedConfig = Autoload
                    end

                    return Autoload
                end
                function SaveManager:LoadAutoloadConfig()
                    if not Library.SettingsLoaded and InterfaceManager then
                        InterfaceManager:Load()
                    end

                    local Name = self:RefreshState()

                    if not Name then
                        return false, 'No config available to autoload'
                    end
                    if self.AutoloadLoaded and Library.ActiveConfig == Name then
                        return true, Name, 0, 0, 0
                    end

                    local Success, NameOrError, AppliedCount, PendingCount, ErrorCount = self:Load(Name, {PreserveEdits = true})

                    if Success then
                        self.AutoloadLoaded = true
                    end

                    return Success, NameOrError, AppliedCount, PendingCount, ErrorCount
                end
                function SaveManager:SetConfigPerAccount(Enabled)
                    Enabled = Enabled == true

                    if self.ConfigPerAccount == Enabled then
                        return true, Enabled
                    end

                    local PreviousEnabled = self.ConfigPerAccount
                    local PreviousActive = Library.ActiveConfig

                    if Library.AutoSaveDirty and Library.ActiveConfig then
                        local Saved, SaveError = Library:FlushAutoSave(true)

                        if not Saved then
                            return false, SaveError
                        end
                    end

                    local function Rollback(ErrorText)
                        InvalidateFolderTreeCache()

                        self.ConfigPerAccount = PreviousEnabled
                        Library.ConfigPerAccount = PreviousEnabled
                        Library.SelectedConfig = nil
                        Library.ActiveConfig = nil
                        Library.AutoSaveDirty = false
                        Library.AutoSaveToken = Library.AutoSaveToken + 1
                        Library.AutoSaveQueued = false
                        Library.PendingAutoSaveFlags = {}
                        self.AutoloadLoaded = false
                        self.PendingObjects = {}

                        self:BuildFolderTree()

                        local Adopted = self:RefreshState()
                        local Restore = (self:ConfigExists(PreviousActive) and PreviousActive) or Adopted

                        if Restore then
                            self:Load(Restore)
                        end

                        return false, ErrorText
                    end

                    InvalidateFolderTreeCache()

                    self.ConfigPerAccount = Enabled
                    Library.ConfigPerAccount = Enabled
                    Library.SelectedConfig = nil
                    Library.ActiveConfig = nil
                    Library.AutoSaveDirty = false
                    Library.AutoSaveToken = Library.AutoSaveToken + 1
                    Library.AutoSaveQueued = false
                    Library.PendingAutoSaveFlags = {}
                    self.AutoloadLoaded = false
                    self.PendingObjects = {}

                    local TreeSuccess, TreeError = self:BuildFolderTree()

                    if not TreeSuccess then
                        return Rollback(TreeError)
                    end

                    local Adopted = self:RefreshState()

                    if Adopted then
                        local Loaded, NameOrError = self:Load(Adopted)

                        if not Loaded then
                            return Rollback(NameOrError)
                        end
                    else
                        local Created, NameOrError = self:Save('default')

                        if not Created then
                            return Rollback(NameOrError)
                        end

                        local Marked, MarkError = self:SetAutoload('default')

                        if not Marked then
                            return Rollback(MarkError)
                        end
                    end

                    return true, Enabled
                end
                function SaveManager:BuildConfigSection(Tab)
                    self.ConfigTab = Tab

                    return Tab
                end

                Library.SaveManager = SaveManager
                InterfaceManager = {Library = Library}

                function InterfaceManager:GetPath()
                    return SaveManager:GetBaseFolder() .. '/options.json'
                end
                function InterfaceManager:Encode(Value)
                    if typeof(Value) == 'Color3' then
                        return {
                            type = 'Color3',
                            value = Value:ToHex(),
                        }
                    elseif typeof(Value) == 'EnumItem' then
                        return {
                            type = 'EnumItem',
                            value = tostring(Value),
                        }
                    elseif type(Value) == 'table' then
                        local Encoded = {}

                        for Key, Item in Value do
                            Encoded[Key] = self:Encode(Item)
                        end

                        return Encoded
                    end

                    return Value
                end
                function InterfaceManager:Decode(Value)
                    if type(Value) == 'table' and Value.type == 'Color3' then
                        local Success, Color = pcall(Color3.fromHex, tostring(Value.value or ''))

                        return Success and Color or nil
                    elseif type(Value) == 'table' and Value.type == 'EnumItem' then
                        local EnumType, EnumName = tostring(Value.value or ''):match('^Enum%.([^.]+)%.(.+)$')
                        local Success, EnumValue = pcall(function()
                            return Enum[EnumType][EnumName]
                        end)

                        return Success and EnumValue or nil
                    elseif type(Value) == 'table' then
                        local Decoded = {}

                        for Key, Item in Value do
                            Decoded[Key] = self:Decode(Item)
                        end

                        return Decoded
                    end

                    return Value
                end
                function InterfaceManager:Save()
                    if type(writefile) ~= 'function' then
                        return false, 'File APIs unavailable'
                    end

                    local FolderSuccess, FolderError = EnsureFolderTree(SaveManager:GetBaseFolder())

                    if not FolderSuccess then
                        return false, FolderError
                    end

                    local Values = {}

                    for Flag, Value in Library.Flags do
                        local Control = Library.FlagControls[Flag]

                        if Library:IsSettingsFlag(Flag) and not (Control and Control.Locked == true) then
                            Values[Flag] = self:Encode(Value)
                        end
                    end

                    local AccountSetting = Library.FlagControls.settings_config_per_account

                    if not (AccountSetting and AccountSetting.Locked == true) then
                        Values.settings_config_per_account = SaveManager.ConfigPerAccount == true
                    end

                    local EncodeSuccess, Encoded = pcall(HttpService.JSONEncode, HttpService, {
                        version = 1,
                        values = Values,
                    })

                    if not EncodeSuccess then
                        return false, 'Failed to encode interface settings'
                    end

                    local Success, ErrorText = pcall(writefile, self:GetPath(), Encoded)

                    if Success then
                        return true, nil
                    end

                    return false, tostring(ErrorText)
                end
                function InterfaceManager:Load()
                    if Library.SettingsLoaded then
                        return true, {}, nil
                    end

                    local Path = self:GetPath()

                    if type(readfile) ~= 'function' or type(isfile) ~= 'function' or not isfile(Path) then
                        Library.SettingsLoaded = true

                        return false, {}, nil
                    end

                    local ReadSuccess, Content = pcall(readfile, Path)

                    if not ReadSuccess then
                        Library.SettingsLoaded = true

                        return false, {}, tostring(Content)
                    end

                    local DecodeSuccess, Data = pcall(HttpService.JSONDecode, HttpService, Content)

                    if not DecodeSuccess or type(Data) ~= 'table' or type(Data.values) ~= 'table' then
                        Library.SettingsLoaded = true

                        return false, {}, 'Interface settings are corrupted'
                    end

                    Library.LoadingSettings = true
                    SaveManager.ConfigPerAccount = Data.values.settings_config_per_account == true
                    Library.ConfigPerAccount = SaveManager.ConfigPerAccount

                    local SettingsErrors = {}

                    for Flag, Encoded in Data.values do
                        if Library:IsSettingsFlag(Flag) then
                            local Value = self:Decode(Encoded)

                            if Value == nil then
                                TableInsert(SettingsErrors, tostring(Flag))
                            else
                                Library.Flags[Flag] = Value

                                local Control = Library.FlagControls[Flag]

                                if Control and Control.Set then
                                    local Applied = pcall(Control.Set, Control, Value, {Silent = true})

                                    if not Applied then
                                        TableInsert(SettingsErrors, tostring(Flag))
                                    end
                                end
                            end
                        end
                    end

                    if Library.ApplyCustomPalette and Library.Flags.settings_palette then
                        Library:ApplyCustomPalette(Library.Flags.settings_palette)
                    end

                    Library.LoadingSettings = false
                    Library.SettingsLoaded = true
                    Library.SettingsDirty = false
                    Library.LastSettingsErrors = SettingsErrors

                    if #SettingsErrors > 0 then
                        return true, Data, 'Skipped settings: ' .. TableConcat(SettingsErrors, ', ')
                    end

                    return true, Data, nil
                end

                Library.InterfaceManager = InterfaceManager
                Library.RegisterOption = function(self, Control, OptionType)
                    if not Control or type(Control.Flag) ~= 'string' or Control.Flag == '' then
                        return Control
                    end

                    Control.Type = OptionType or Control.Type

                    if not Control.SetValue and Control.Set then
                        Control.SetValue = function(Option, Value, ...)
                            return Option:Set(Value, ...)
                        end
                    end
                    if Control.Type == 'Colorpicker' and not Control.SetValueRGB then
                        Control.SetValueRGB = function(
                            Option,
                            Value,
                            _,
                            Options
                        )
                            return Option:Set(Value, Options)
                        end
                    end
                    if Control.Type == 'Dropdown' and not Control.SetValues and Control.Refresh then
                        Control.SetValues = function(Option, Values)
                            return Option:Refresh(Values)
                        end
                    end

                    local Existing = self.FlagControls[Control.Flag]

                    if Existing and Existing ~= Control then
                        warn(StringFormat(
[[[Vellure] Flag %q is already used by %q; %q will overwrite it in configs.]], tostring(Control.Flag), tostring(Existing.Name or '?'), tostring(Control.Name or '?')))
                    end

                    self.FlagControls[Control.Flag] = Control

                    if Control.Type then
                        self.Options[Control.Flag] = Control
                        Control.DefaultSnapshot = Control.DefaultSnapshot or SaveManager:EncodeOption(Control.Flag, Control)

                        local Parked = SaveManager.PendingObjects[Control.Flag]

                        if Parked and not self:IsSettingsFlag(Control.Flag) then
                            local WasLoading = self.LoadingConfig

                            self.LoadingConfig = true

                            local Success, Applied = pcall(SaveManager.ApplyOption, SaveManager, Parked)

                            self.LoadingConfig = WasLoading

                            if Success and Applied then
                                SaveManager.PendingObjects[Control.Flag] = nil
                            end
                        end
                    end

                    return Control
                end
                Library.SaveSettings = function(self)
                    local Success, ErrorText = InterfaceManager:Save()

                    if Success then
                        self.SettingsDirty = false
                    end

                    return Success, ErrorText
                end
                Library.LoadSettings = function(self)
                    return InterfaceManager:Load()
                end
                Library.QueueSettingsSave = function(self)
                    if not self.SettingsLoaded or self.LoadingSettings or self.IsUnloading then
                        return false
                    end

                    self.SettingsDirty = true

                    if self.SettingsSaveQueued then
                        return true
                    end

                    self.SettingsSaveQueued = true

                    task.delay(0.2, function()
                        self.SettingsSaveQueued = false

                        if self.IsUnloading or not self.SettingsDirty then
                            return
                        end

                        local Success, ErrorText = self:SaveSettings()

                        if not Success then
                            self:Notify({
                                Title = 'Settings save failed',
                                Content = tostring(ErrorText),
                                Duration = 4,
                            })
                        end
                    end)

                    return true
                end
                Library.SaveConfig = function(self, Name)
                    Name = self:NormalizeConfigName(Name)

                    if self.AutoSaveDirty and self.ActiveConfig and self.ActiveConfig ~= Name then
                        local Saved, SaveError = self:FlushAutoSave(true)

                        if not Saved then
                            return false, SaveError
                        end
                    end

                    return SaveManager:Save(Name)
                end
                Library.LoadConfig = function(self, Name, Options)
                    Name = self:NormalizeConfigName(Name)

                    if self.AutoSaveDirty and self.ActiveConfig and self.ActiveConfig ~= Name then
                        local Saved, SaveError = self:FlushAutoSave(true)

                        if not Saved then
                            return false, SaveError
                        end
                    end

                    return SaveManager:Load(Name, Options)
                end
                Library.DeleteConfig = function(self, Name)
                    return SaveManager:Delete(Name)
                end
                Library.ListConfigs = function(self)
                    return SaveManager:RefreshConfigList()
                end
                Library.GetSelectedConfig = function(self)
                    return self.SelectedConfig
                end
                Library.SetSelectedConfig = function(self, Name)
                    Name = self:NormalizeConfigName(Name)

                    if Name and not SaveManager:ConfigExists(Name) then
                        return false, 'Config not found'
                    end

                    self.SelectedConfig = Name

                    return true, Name
                end
                Library.GetAutoLoadConfig = function(self)
                    return self.AutoLoadConfig
                end
                Library.SetAutoLoadConfig = function(self, Name)
                    return SaveManager:SetAutoload(Name)
                end
                Library.GetConfigPerAccount = function()
                    return SaveManager.ConfigPerAccount == true
                end
                Library.SetConfigPerAccount = function(self, Enabled)
                    local Success, StateOrError = SaveManager:SetConfigPerAccount(Enabled)

                    if Success then
                        self.Flags.settings_config_per_account = StateOrError
                        self.SettingsDirty = true

                        local Saved, SettingsError = self:SaveSettings()

                        if not Saved then
                            self.SettingsDirty = true

                            self:QueueSettingsSave()
                            self:Notify({
                                Title = 'Settings save failed',
                                Content = tostring(SettingsError),
                                Duration = 4,
                            })
                        end
                    end

                    return Success, StateOrError
                end
                Library.QueueAutoSave = function(self, Flag, Internal)
                    if self.IsUnloading then
                        return false
                    end
                    if not Internal then
                        self.AutoSaveRevision = self.AutoSaveRevision + 1
                        self.AutoSaveRetryCount = 0

                        if type(Flag) == 'string' and Flag ~= '' then
