                local ResizePointerStart
                local ResizeScale = 1
                local ResizeInput
                local ResizeMoveConnection
                local ResizeEndConnection

                Library:Connect(scope.Items['ResizeHitbox'].Instance.MouseEnter, function(
                )
                    if scope.Window.IsMobile or scope.Window.IsResizing then
                        return
                    end

                    TweenService:Create(scope.Items['ResizeHandle'].Instance, TweenInfo.new(0.2, Enum.EasingStyle.Quart), {
                        ImageColor3 = Library.Theme.Accent,
                        ImageTransparency = 0.08,
                    }):Play()
                end)
                Library:Connect(scope.Items['ResizeHitbox'].Instance.MouseLeave, function(
                )
                    if scope.Window.IsMobile or scope.Window.IsResizing then
                        return
                    end

                    TweenService:Create(scope.Items['ResizeHandle'].Instance, TweenInfo.new(0.2, Enum.EasingStyle.Quart), {
                        ImageColor3 = Library.Theme['Muted Text'],
                        ImageTransparency = 0.42,
                    }):Play()
                end)
                Library:Connect(scope.Items['ResizeHitbox'].Instance.InputBegan, function(
                    Input
                )
                    if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
                        return
                    end

                    local MainFrame = scope.Items['MainFrame'].Instance

                    if scope.Window.IsResizing or not scope.Window.IsOpen or not MainFrame.Visible then
                        return
                    end

                    scope.Window.IsResizing = true
                    scope.Window.UserMoved = true
                    ResizeInput = Input
                    ResizePointerStart = Input.UserInputType == Enum.UserInputType.Touch and Vector2New(Input.Position.X, Input.Position.Y) or UserInputService:GetMouseLocation()
                    ResizeStartSize = Vector2New(MainFrame.Size.X.Offset, MainFrame.Size.Y.Offset)
                    ResizeScale = math.max(tonumber(scope.Items['MainUIScale'].Instance.Scale) or 1, 0.01)

                    if Workspace.CurrentCamera then
                        local ViewportSize = Workspace.CurrentCamera.ViewportSize

                        ResizeStartPosition = Vector2New(MathFloor((ViewportSize.X * MainFrame.Position.X.Scale) + MainFrame.Position.X.Offset + 0.5), MathFloor((ViewportSize.Y * MainFrame.Position.Y.Scale) + MainFrame.Position.Y.Offset + 0.5))
                        MainFrame.Position = UDim2New(0, ResizeStartPosition.X, 0, ResizeStartPosition.Y)
                    else
                        ResizeStartPosition = Vector2New(MainFrame.Position.X.Offset, MainFrame.Position.Y.Offset)
                    end

                    ResizeStartTopLeft = Vector2New(ResizeStartPosition.X - (ResizeStartSize.X * ResizeScale * MainFrame.AnchorPoint.X), ResizeStartPosition.Y - (ResizeStartSize.Y * ResizeScale * MainFrame.AnchorPoint.Y))

                    TweenService:Create(scope.Items['ResizeHandle'].Instance, TweenInfo.new(0.3, Enum.EasingStyle.Quart), {
                        Size = UDim2New(0, 15, 0, 15),
                        ImageColor3 = Library.Theme.Text,
                        ImageTransparency = 0,
                    }):Play()
                    DisconnectConnectionObject(ResizeMoveConnection)
                    DisconnectConnectionObject(ResizeEndConnection)

                    ResizeMoveConnection = Library:Connect(UserInputService.InputChanged, function(
                        ChangedInput
                    )
                        if not scope.Window.IsResizing then
                            return
                        end
                        if ChangedInput.UserInputType ~= Enum.UserInputType.MouseMovement and ChangedInput.UserInputType ~= Enum.UserInputType.Touch then
                            return
                        end
                        if ChangedInput.UserInputType == Enum.UserInputType.Touch and ChangedInput ~= ResizeInput then
                            return
                        end

                        local PointerPosition = ChangedInput.UserInputType == Enum.UserInputType.Touch and Vector2New(ChangedInput.Position.X, ChangedInput.Position.Y) or UserInputService:GetMouseLocation()
                        local Delta = (PointerPosition - ResizePointerStart) / ResizeScale
                        local TargetWidth = math.max(scope.Window.MinSize.X, ResizeStartSize.X + Delta.X)
                        local TargetHeight = math.max(scope.Window.MinSize.Y, ResizeStartSize.Y + Delta.Y)

                        if Workspace.CurrentCamera then
                            local ViewportSize = Workspace.CurrentCamera.ViewportSize
                            local _, BottomRightInset = GuiService:GetGuiInset()
                            local MaxWidth = math.max(scope.Window.MinSize.X, (ViewportSize.X - BottomRightInset.X - ResizeStartTopLeft.X - 12) / ResizeScale)
                            local MaxHeight = math.max(scope.Window.MinSize.Y, (ViewportSize.Y - BottomRightInset.Y - ResizeStartTopLeft.Y - 12) / ResizeScale)

                            TargetWidth = math.min(TargetWidth, MaxWidth)
                            TargetHeight = math.min(TargetHeight, MaxHeight)
                        end

                        TargetWidth = MathFloor(TargetWidth + 0.5)
                        TargetHeight = MathFloor(TargetHeight + 0.5)

                        local TargetSize = UDim2New(0, TargetWidth, 0, TargetHeight)
                        local TargetPosition = UDim2New(0, MathFloor(ResizeStartPosition.X + ((TargetWidth - ResizeStartSize.X) * ResizeScale * MainFrame.AnchorPoint.X) + 0.5), 0, MathFloor(ResizeStartPosition.Y + ((TargetHeight - ResizeStartSize.Y) * ResizeScale * MainFrame.AnchorPoint.Y) + 0.5))

                        scope.Window.DefaultSize = Vector2New(TargetWidth, TargetHeight)
                        scope.Window.OpenSize = TargetSize

                        local ResizeSpeed = MathClamp(tonumber(Library.ResizeSmoothness) or 0.4, 0, 1)

                        if ResizeSpeed <= 0 then
                            MainFrame.Size = TargetSize
                            MainFrame.Position = TargetPosition
                        else
                            MainFrame:TweenSizeAndPosition(TargetSize, TargetPosition, Enum.EasingDirection.Out, Enum.EasingStyle.Quint, ResizeSpeed, true)
                        end
                    end)
                    ResizeEndConnection = Library:Connect(UserInputService.InputEnded, function(
                        EndInput
                    )
                        if EndInput.UserInputType ~= Enum.UserInputType.MouseButton1 and EndInput.UserInputType ~= Enum.UserInputType.Touch then
                            return
                        end
                        if EndInput.UserInputType == Enum.UserInputType.Touch and EndInput ~= ResizeInput then
                            return
                        end

                        scope.Window.IsResizing = false
                        ResizeInput = nil
                        ResizePointerStart = nil
                        ResizeStartSize = nil
                        ResizeStartPosition = nil
                        ResizeStartTopLeft = nil

                        DisconnectConnectionObject(ResizeMoveConnection)

                        ResizeMoveConnection = nil

                        DisconnectConnectionObject(ResizeEndConnection)

                        ResizeEndConnection = nil

                        local IsHovered = not scope.Window.IsMobile and Library:IsMouseOverFrame(scope.Items['ResizeHitbox'])

                        TweenService:Create(scope.Items['ResizeHandle'].Instance, TweenInfo.new(0.3, Enum.EasingStyle.Quart), {
                            Size = UDim2New(0, scope.Window.IsMobile and 24 or 20, 0, scope.Window.IsMobile and 24 or 20),
