                        }):Play()
                    end)
                end)

                function scope.SyncMainShadow()
                    pcall(function()
                        local MainFrame = scope.Items['MainFrame'] and scope.Items['MainFrame'].Instance

                        if not MainFrame then
                            return
                        end

                        local ShadowFrame = scope.Items['Shadow'] and scope.Items['Shadow'].Instance

                        if ShadowFrame then
                            ShadowFrame.AnchorPoint = MainFrame.AnchorPoint

                            if not scope.Window.ShadowDragSyncing then
                                ShadowFrame.Position = MainFrame.Position
                            end

                            ShadowFrame.Size = MainFrame.Size
                            ShadowFrame.ZIndex = math.max(0, MainFrame.ZIndex - 1)
                            ShadowFrame.Visible = MainFrame.Visible
                        end
                        if scope.Items['ShadowUIScale'] and scope.Items['ShadowUIScale'].Instance and scope.Items['MainUIScale'] and scope.Items['MainUIScale'].Instance then
                            scope.Items['ShadowUIScale'].Instance.Scale = scope.Items['MainUIScale'].Instance.Scale
                        end

                        local MainShadow = scope.Items['MainShadow'] and scope.Items['MainShadow'].Instance

                        if not MainShadow then
                            local ExistingShadow = ShadowFrame and (ShadowFrame:FindFirstChild('ImageLabel') or ShadowFrame:FindFirstChild('shadow'))

                            if ExistingShadow and ExistingShadow:IsA('GuiObject') then
                                scope.Items['MainShadow'] = {Instance = ExistingShadow}
                                MainShadow = ExistingShadow
                            end
                        end
                        if MainShadow then
                            MainShadow.Parent = ShadowFrame or Library.Holder.Instance
                            MainShadow.Name = 'ImageLabel'
                            MainShadow.AnchorPoint = Vector2New(0.5, 0.5)
                            MainShadow.Position = UDim2New(0.5, 0, 0.5, 0)
                            MainShadow.Size = UDim2New(1, 64, 1, 64)
                            MainShadow.ZIndex = ShadowFrame and ShadowFrame.ZIndex or math.max(0, MainFrame.ZIndex - 1)
                            MainShadow.Visible = MainFrame.Visible and scope.Window.GlowEnabled
                            MainShadow.ImageTransparency = 1 - (scope.Window.GlowIntensity or 0.7) * 0.72
                        end

                        local MainShadowSnake = scope.Items['MainShadowSnake'] and scope.Items['MainShadowSnake'].Instance

                        if MainShadowSnake then
                            MainShadowSnake.AnchorPoint = MainFrame.AnchorPoint

                            if not scope.Window.ShadowDragSyncing then
                                MainShadowSnake.Position = MainFrame.Position
                            end

                            MainShadowSnake.Size = UDim2New(MainFrame.Size.X.Scale, MainFrame.Size.X.Offset + 160, MainFrame.Size.Y.Scale, MainFrame.Size.Y.Offset + 160)
                            MainShadowSnake.Visible = MainFrame.Visible and scope.Window.RotateGradientEnabled and scope.Window.GlowEnabled
                        end

                        local MainGlowClip = scope.Items['MainGlowClip'] and scope.Items['MainGlowClip'].Instance

                        if MainGlowClip then
                            MainGlowClip.Parent = MainFrame
                            MainGlowClip.AnchorPoint = Vector2New(0.5, 0.5)
                            MainGlowClip.Position = UDim2New(0.5, 0, 0.5, 0)
                            MainGlowClip.Size = UDim2New(1, 0, 1, 0)
                            MainGlowClip.ZIndex = MainFrame.ZIndex
                            MainGlowClip.Visible = MainFrame.Visible and scope.Window.GlowEnabled
                        end
                        if scope.Items['MainClipGlow'] and scope.Items['MainClipGlow'].Instance then
                            scope.Items['MainClipGlow'].Instance.Position = UDim2New(0, 0, 0.5, 0)
                            scope.Items['MainClipGlow'].Instance.Size = UDim2New(0, 600, 0, 600)
                            scope.Items['MainClipGlow'].Instance.ZIndex = MainGlowClip and MainGlowClip.ZIndex or MainFrame.ZIndex
                            scope.Items['MainClipGlow'].Instance.Visible = MainFrame.Visible and scope.Window.GlowEnabled
                        end
                        if scope.Items['MainClipGlow1'] and scope.Items['MainClipGlow1'].Instance then
                            scope.Items['MainClipGlow1'].Instance.Position = UDim2New(1, 0, 0.5, 
-20)
                            scope.Items['MainClipGlow1'].Instance.Size = UDim2New(0, 400, 0, 400)
