                local function UpdateUserIdentitySize()
                    pcall(function()
                        scope.Items['User'].Instance.Size = UDim2New(0, scope.Window.IconBarWidth - 36, 0, 48)
                        scope.Items['UserIdentity'].Instance.Position = UDim2New(0, 40, 0.5, 
-14)
                        scope.Items['UserIdentity'].Instance.Size = UDim2New(1, 
-40, 0, 28)
                        scope.Items['UserUsername'].Instance.Size = UDim2New(1, 0, 0, 13)
                        scope.Items['UserDisplayName'].Instance.Size = UDim2New(1, 0, 0, 12)
                    end)
                end

                Library:Connect(scope.Items['UserUsername'].Instance:GetPropertyChangedSignal('TextBounds'), UpdateUserIdentitySize)
                Library:Connect(scope.Items['UserDisplayName'].Instance:GetPropertyChangedSignal('TextBounds'), UpdateUserIdentitySize)
                task.defer(UpdateUserIdentitySize)

                function scope.Window:SyncUserIdentity()
                    local LinkedDiscordId = tostring(getgenv().LRM_LinkedDiscordID or '')
                    local IsPremium = getgenv().LRM_IsUserPremium == true and LinkedDiscordId ~= ''
                    local Profile = scope.Window.DiscordProfile

                    scope.Items['UserHeadshot'].Instance.Image = VellureLogoImage
                    scope.Items['UserHeadshot'].Instance.ImageColor3 = FromRGB(255, 255, 255)
                    scope.Items['UserUsername'].Instance.Text = 'Vellure'
                    scope.Items['UserDisplayName'].Instance.Text = 'discord.gg/vellure'
                    scope.Items['UserStatus'].Instance.Visible = false

                    if not IsPremium then
                        return
                    end

                    local Username = type(Profile) == 'table' and tostring(Profile.username or Profile.Username or '') or ''
                    local DisplayName = type(Profile) == 'table' and tostring(Profile.global_name or Profile.display_name or Profile.DisplayName or '') or ''
                    local Avatar = type(Profile) == 'table' and tostring(Profile.avatar_url or Profile.AvatarUrl or Profile.avatar_asset or Profile.Avatar or '') or ''
                    local AvatarHash = type(Profile) == 'table' and tostring(Profile.avatar_hash or Profile.avatar or '') or ''

                    scope.Items['UserUsername'].Instance.Text = DisplayName ~= '' and DisplayName or (Username ~= '' and Username or 'Premium user')
                    scope.Items['UserDisplayName'].Instance.Text = Username ~= '' and ('@' .. Username) or ('Discord ' .. LinkedDiscordId)
                    scope.Items['UserStatus'].Instance.Visible = true

                    if Avatar == '' and AvatarHash ~= '' and not StringFind(AvatarHash, '://', 1, true) then
                        Avatar = 'https://cdn.discordapp.com/avatars/' .. LinkedDiscordId .. '/' .. AvatarHash .. '.png?size=128'
                    end
                    if Avatar == '' then
                        return
                    end
                    if not StringFind(Avatar, '://', 1, true) then
                        scope.Items['UserHeadshot'].Instance.Image = Avatar

                        return
                    end
                    if type(writefile) ~= 'function' or not GetCustomAsset then
                        return
                    end

                    task.defer(function()
                        local AvatarPath = Library.Folders.UI .. '/discord-' .. LinkedDiscordId .. '.png'
                        local HasCachedAvatar = type(isfile) == 'function' and isfile(AvatarPath)

                        if not HasCachedAvatar then
                            local Downloaded, AvatarBytes = pcall(game.HttpGet, game, Avatar)

                            if not Downloaded or type(AvatarBytes) ~= 'string' or #AvatarBytes < 64 then
                                return
                            end

                            local Written = pcall(writefile, AvatarPath, AvatarBytes)

                            if not Written then
                                return
                            end
                        end

                        local Loaded, AvatarAsset = pcall(GetCustomAsset, AvatarPath)

                        if Loaded and type(AvatarAsset) == 'string' and not Library.IsUnloading and tostring(getgenv().LRM_LinkedDiscordID or '') == LinkedDiscordId then
                            scope.Items['UserHeadshot'].Instance.Image = AvatarAsset
                        end
                    end)
                end

                task.defer(function()
                    if not Library.IsUnloading then
                        scope.Window:SyncUserIdentity()
                    end
                end)

