                    self:SetTheme(Name)

                    if self.ActiveWindow and self.ActiveWindow.RefreshThemeCards then
                        self.ActiveWindow:RefreshThemeCards()
                    end

                    return true
                end
                function L:DeleteTheme(Name)
                    if not self.CustomThemes[Name] then
                        return false, 'Select a saved theme.'
                    end

                    local Next = table.clone(self.CustomThemes)

                    Next[Name] = nil

                    local OK, Error = self:WriteUIJson(Path, Next)

                    if not OK then
                        return false, tostring(Error)
                    end

                    self.CustomThemes = Next

                    if self.CurrentTheme == Name then
                        self:SetTheme('Dark')
                    end

                    Presets[Name] = nil

                    if self.ActiveWindow and self.ActiveWindow.RefreshThemeCards then
                        self.ActiveWindow:RefreshThemeCards()
                    end

                    return true
                end
            end
