                    'Accent',
                    'Background',
                    'Sidebar',
                    'Element',
                    'Text',
                    'Muted Text',
                }

                Library.CustomColors = {}
                Library.ApplyCustomPalette = function(self, Encoded)
                    local OK, Values = pcall(context.HttpService.JSONDecode, context.HttpService, tostring(Encoded or '{}'))

                    if not OK or type(Values) ~= 'table' then
                        return false
                    end

                    local Patch = {}

                    self.CustomColors = {}

                    for _, Role in Roles do
                        if type(Values[Role]) == 'string' then
                            local Valid, Color = pcall(Color3.fromHex, Values[Role])

                            if Valid then
                                Patch[Role] = Color
