                            self.Flags[Flag] = Patch.Accent

                            local Option = self.Options[Flag]

                            if Option then
                                Option.Value = Patch.Accent
                                Option.Color = Patch.Accent
                            end
                        end
                    end
                    if Patch.Background then
                        Patch.Inline = Patch.Background:Lerp(Patch.Text or self.Theme.Text, 0.035)
                    end
                    if Patch.Element then
                        Patch.Popup = Patch.Element
