                            if Dropdown.Priority then
                                local function CommitPriority()
                                    local OptionData = PoolItem.EditOption or PoolItem.Option
                                    local PreviousPriority = PoolItem.EditPriority or (OptionData and Dropdown.Value[OptionData.Name]) or 1

                                    if Dropdown.Locked or not OptionData then
                                        return
                                    end

                                    PoolItem.EditOption = nil
                                    PoolItem.EditPriority = nil

                                    local RawText = PoolItem.EditText or PoolPriority.Instance.Text

                                    PoolItem.EditText = nil

                                    local Priority = MathFloor(tonumber((StringGSub(RawText, '[^%d]', ''))) or 0)

                                    if not Dropdown:SetPriority(OptionData.Name, Priority) then
                                        PoolPriority.Instance.Text = tostring(PreviousPriority)
                                    end

                                    Dropdown:RenderPool()
                                end

                                Library:Connect(PoolPriority.Instance.Focused, function(
                                )
                                    PoolItem.EditOption = PoolItem.Option
                                    PoolItem.EditPriority = PoolItem.Option and Dropdown.Value[PoolItem.Option.Name] or nil

                                    task.defer(function()
                                        if PoolPriority.Instance:IsFocused() then
                                            PoolPriority.Instance.CursorPosition = #PoolPriority.Instance.Text + 1
                                            PoolPriority.Instance.SelectionStart = 1
                                        end
                                    end)
                                    TweenService:Create(PoolPriority.Instance, TweenInfo.new(0.16, Enum.EasingStyle.Exponential), {
                                        BackgroundTransparency = 0.45,
