                                end)
                                Library:Connect(PoolPriority.Instance.FocusLost, function(
                                )
                                    CommitPriority()
                                end)
                                PoolPriority:Connect('MouseEnter', function()
                                    if not PoolPriority.Instance:IsFocused() then
                                        TweenService:Create(PoolPriority.Instance, TweenInfo.new(0.16, Enum.EasingStyle.Exponential), {BackgroundTransparency = 0.68}):Play()
                                        TweenService:Create(PoolPriorityStroke.Instance, TweenInfo.new(0.16, Enum.EasingStyle.Exponential), {Transparency = 0.78}):Play()
                                    end
                                end)
                                PoolPriority:Connect('MouseLeave', function()
                                    if not PoolPriority.Instance:IsFocused() then
                                        TweenService:Create(PoolPriority.Instance, TweenInfo.new(0.22, Enum.EasingStyle.Exponential), {BackgroundTransparency = 1}):Play()
                                        TweenService:Create(PoolPriorityStroke.Instance, TweenInfo.new(0.22, Enum.EasingStyle.Exponential), {Transparency = 1}):Play()
                                    end
                                end)
                                Library:Connect(PoolButton.Instance.InputBegan, function(
                                    Input
                                )
                                    if Dropdown.Locked or not PoolItem.Option then
                                        return
                                    end
                                    if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
                                        return
                                    end
                                    if Input.Position.X >= PoolPriority.Instance.AbsolutePosition.X - 4 then
                                        return
                                    end

                                    Dropdown.DragOption = PoolItem.Option.Name
                                    Dropdown.DragPoolItem = PoolItem
                                    Dropdown.DragStartPosition = Input.Position
                                    Dropdown.DragInput = Input
                                    Dropdown.DragStarted = false
                                    Dropdown.DragChanged = false
                                    Dropdown.DragVisualY = nil
                                    Dropdown.DragGrabOffsetY = Input.Position.Y - PoolButton.Instance.AbsolutePosition.Y
                                    Dropdown.DragScrollAt = 0
                                    Items['Holder'].Instance.ScrollingEnabled = false
                                end)
                            end

                            TableInsert(Dropdown.Pool, PoolItem)
                        end

                        if Dropdown.Priority then
                            Library:Connect(UserInputService.InputChanged, function(
                                Input
                            )
                                if not Dropdown.DragInput or not Dropdown.IsOpen or not Dropdown.DragOption then
                                    return
                                end
                                if Input.UserInputType ~= Enum.UserInputType.MouseMovement and Input.UserInputType ~= Enum.UserInputType.Touch then
                                    return
                                end
                                if Input.UserInputType == Enum.UserInputType.Touch and Input ~= Dropdown.DragInput then
                                    return
                                end
                                if not Dropdown.DragStarted then
                                    local Delta = Input.Position - Dropdown.DragStartPosition

                                    if math.abs(Delta.X) < 5 and math.abs(Delta.Y) < 5 then
                                        return
                                    end

                                    Dropdown.DragStarted = true
                                end

                                local VisibleOptions = Dropdown:GetVisibleOptions()
                                local PointerY = Input.Position.Y
                                local Holder = Items['Holder'].Instance
                                local Now = os.clock()

                                if Now - (Dropdown.DragScrollAt or 0) >= 0.08 then
                                    if PointerY < Holder.AbsolutePosition.Y + 10 then
                                        Holder.CanvasPosition = Vector2New(0, MathClamp(Holder.CanvasPosition.Y - Dropdown.OptionHeight, 0, math.max(0, #VisibleOptions * Dropdown.OptionHeight - Holder.AbsoluteSize.Y)))
                                        Dropdown.DragScrollAt = Now
                                    elseif PointerY > Holder.AbsolutePosition.Y + Holder.AbsoluteSize.Y - 10 then
                                        Holder.CanvasPosition = Vector2New(0, MathClamp(Holder.CanvasPosition.Y + Dropdown.OptionHeight, 0, math.max(0, #VisibleOptions * Dropdown.OptionHeight - Holder.AbsoluteSize.Y)))
                                        Dropdown.DragScrollAt = Now
                                    end
                                end

                                local Scale = math.max(tonumber(Dropdown.Window and Dropdown.Window.ResponsiveUIScale) or 1, 0.01)
                                local CanvasY = (PointerY - Holder.AbsolutePosition.Y) / Scale + Holder.CanvasPosition.Y
                                local TargetIndex = MathClamp(MathFloor(CanvasY / Dropdown.OptionHeight) + 1, 1, #VisibleOptions)
                                local TargetOption = VisibleOptions[TargetIndex]

                                if TargetOption and TargetOption.Name ~= Dropdown.DragOption then
                                    local DragIndex
                                    local Priorities = {}

                                    for Index, OptionData in VisibleOptions do
                                        Priorities[Index] = Dropdown.Value[OptionData.Name]

                                        if OptionData.Name == Dropdown.DragOption then
                                            DragIndex = Index
                                        end
                                    end

                                    if DragIndex then
                                        local DraggedOption = table.remove(VisibleOptions, DragIndex)

                                        table.insert(VisibleOptions, TargetIndex, DraggedOption)

                                        local NextValues = TableClone(Dropdown.Value)

                                        for Index, OptionData in VisibleOptions do
                                            NextValues[OptionData.Name] = Priorities[Index]
                                        end

                                        Dropdown.Value = NextValues
                                        Library.Flags[Dropdown.Flag] = TableClone(NextValues)

                                        for _, OptionData in Dropdown.OptionOrder do
                                            OptionData.Priority = NextValues[OptionData.Name] or 0
                                            OptionData.Selected = true
                                        end

                                        Dropdown:UpdateValueText()

                                        Dropdown.DragChanged = true

                                        Dropdown:RenderPool()
                                    end
                                end

                                Dropdown.DragVisualY = MathFloor(MathClamp(CanvasY - (Dropdown.DragGrabOffsetY / Scale), 0, math.max(0, #VisibleOptions * Dropdown.OptionHeight - (Dropdown.OptionHeight - 3))) + 0.5)

                                if Dropdown.DragPoolItem and Dropdown.DragPoolItem.Option and Dropdown.DragPoolItem.Option.Name == Dropdown.DragOption then
                                    Dropdown.DragPoolItem.Button.Instance.Position = UDim2New(0, 0, 0, Dropdown.DragVisualY)
                                end
                            end)
                            Library:Connect(UserInputService.InputEnded, function(
                                Input
                            )
                                if not Dropdown.DragInput then
                                    return
                                end
                                if Input.UserInputType ~= Enum.UserInputType.MouseButton1 and Input.UserInputType ~= Enum.UserInputType.Touch then
                                    return
                                end
                                if Input.UserInputType == Enum.UserInputType.Touch and Input ~= Dropdown.DragInput then
