                                Dropdown.DragOption = nil
                                Dropdown.DragPoolItem = nil
                                Dropdown.DragStartPosition = nil
                                Dropdown.DragInput = nil
                                Dropdown.DragStarted = false
                                Dropdown.DragChanged = false
                                Dropdown.DragVisualY = nil
                                Dropdown.DragGrabOffsetY = nil
                                Dropdown.DragScrollAt = nil

                                Dropdown:RenderPool()

                                if Changed then
                                    if Dropdown.Callback then
                                        Library:DispatchOptionCallback(Dropdown, Dropdown:Get())
                                    end
                                    if not Library:IsSettingsFlag(Dropdown.Flag) then
                                        Library:QueueAutoSave(Dropdown.Flag)
                                    end
                                end
                            end)
