                    Items['Dropdown'].Instance:SetAttribute('Searchable', true)
                    Items['Dropdown'].Instance:SetAttribute('SearchType', 'Dropdown')
                    Items['Dropdown'].Instance:SetAttribute('SearchTitle', Dropdown.Name)

                    Dropdown.SearchText = tostring(Dropdown.Name or '') .. ' ' .. tostring(Dropdown.Flag or '') .. ' ' .. tostring(Dropdown.Placeholder or '') .. ' ' .. tostring((Dropdown.Section and Dropdown.Section.Name) or '') .. ' ' .. tostring((Dropdown.Page and Dropdown.Page.Name) or '')

                    Items['Dropdown'].Instance:SetAttribute('SearchKeywords', Dropdown.SearchText)

                    function Dropdown:GetSourceItems()
                        local Source = Dropdown.ItemsSource

                        if type(Source) == 'function' then
                            local Success, Result = pcall(Source, Dropdown)

                            Source = Success and Result or {}
                        end
                        if type(Source) ~= 'table' then
                            return {}
                        end

                        return Source
                    end
                    function Dropdown:GetVisibleOptions()
                        local VisibleOptions = {}
                        local Query = StringLower(tostring(Dropdown.FilterText or ''))
                        local CompactQuery = StringGSub(Query, '[%s_%-%./]+', '')
                        local QueryTokens = {}

                        for Token in string.gmatch(Query, '[%w_%-]+')do
                            if Token ~= '' then
                                TableInsert(QueryTokens, Token)
                            end
                        end
                        for _, OptionData in Dropdown.OptionOrder do
                            local SearchBlob = StringLower(TableConcat({
                                tostring(OptionData.Name or ''),
                                tostring(OptionData.Value or ''),
                                tostring(OptionData.Text or ''),
                                tostring(OptionData.SearchText or ''),
                                tostring(OptionData.Description or ''),
                            }, ' '))
                            local CompactBlob = StringGSub(SearchBlob, '[%s_%-%./]+', '')
                            local Matches = Query == '' or StringFind(SearchBlob, Query, 1, true) ~= nil or (CompactQuery ~= '' and StringFind(CompactBlob, CompactQuery, 1, true) ~= nil)

                            if not Matches and #QueryTokens > 1 then
                                local AllTokensMatch = true

                                for _, Token in QueryTokens do
                                    local CompactToken = StringGSub(Token, '[%s_%-%./]+', '')

                                    if StringFind(SearchBlob, Token, 1, true) == nil and (CompactToken == '' or StringFind(CompactBlob, CompactToken, 1, true) == nil) then
                                        AllTokensMatch = false

                                        break
                                    end
                                end

                                Matches = AllTokensMatch
                            end
                            if not Matches and #QueryTokens == 1 and QueryTokens[1] ~= '' then
                                Matches = StringFind(SearchBlob, QueryTokens[1], 1, true) ~= nil
                            end
                            if Matches then
                                TableInsert(VisibleOptions, OptionData)
                            end
                        end

                        if Dropdown.Priority then
                            table.sort(VisibleOptions, function(First, Second)
                                local FirstPriority = tonumber(First.Priority) or 0
                                local SecondPriority = tonumber(Second.Priority) or 0

                                if FirstPriority ~= SecondPriority then
                                    return FirstPriority > SecondPriority
                                end

                                return (First.Order or 0) < (Second.Order or 0)
                            end)
                        end

                        return VisibleOptions
                    end
                    function Dropdown:UpdateValueText()
                        local HasValue = Dropdown.Multi and next(Dropdown.Value) ~= nil or (not Dropdown.Multi and Dropdown.Value ~= nil and Dropdown.Value ~= '')

                        Items.ClearButton.Instance.Visible = Dropdown.AllowNone and HasValue and not Dropdown.Locked
                        Items.Value.Instance.Size = UDim2New(1, Dropdown.Priority and 
-40 or (Items.ClearButton.Instance.Visible and -60 or -34), 1, 0)
                        Items.Icon.Instance.ImageColor3 = Library.Theme['Muted Text']

                        if Dropdown.Priority then
                            local Prioritized = {}

                            for _, OptionData in Dropdown.OptionOrder do
                                if (tonumber(OptionData.Priority) or 0) > 0 then
                                    TableInsert(Prioritized, OptionData)
                                end
                            end

                            table.sort(Prioritized, function(First, Second)
                                local FirstPriority = tonumber(First.Priority) or 0
                                local SecondPriority = tonumber(Second.Priority) or 0

                                if FirstPriority ~= SecondPriority then
                                    return FirstPriority > SecondPriority
                                end

                                return (First.Order or 0) < (Second.Order or 0)
                            end)

                            local Summary = {}

                            for _, OptionData in Prioritized do
                                TableInsert(Summary, tostring(OptionData.Name))
                            end

                            Dropdown.SummaryText = #Summary > 0 and TableConcat(Summary, ' > ') or Dropdown.NoneText
                            Items['PriorityHint'].Instance.Text = Dropdown.Description
                            Items['Value'].Instance.Text = Dropdown.SummaryText
                            Items['Value'].Instance.TextColor3 = #Summary > 0 and Library.Theme.Text or Library.Theme['Muted Text']
                        elseif Dropdown.Multi then
                            local Count = #Dropdown.Value

                            if Count == 0 then
                                Items['Value'].Instance.Text = Dropdown.NoneText
                                Items['Value'].Instance.TextColor3 = Library.Theme['Muted Text']
                            else
                                Items['Value'].Instance.Text = Count <= 3 and TableConcat(Dropdown.Value, ', ') or StringFormat('%s selected', Count)
                                Items['Value'].Instance.TextColor3 = Library.Theme.Text
                            end
                        else
