                    function Dropdown:RenderPool()
                        if not Dropdown.IsOpen then
                            return
                        end

                        local VisibleOptions = Dropdown:GetVisibleOptions()
                        local Total = #VisibleOptions
                        local ScrollY = Items['Holder'].Instance.CanvasPosition.Y
                        local StartIndex = MathClamp(MathFloor(ScrollY / Dropdown.OptionHeight) + 1, 1, math.max(1, Total))
                        local EndIndex = math.min(Total, StartIndex + #Dropdown.Pool - 1)
                        local Assignments = {}
                        local UsedPoolItems = {}

                        if Dropdown.Priority and Dropdown.DragStarted and Dropdown.DragPoolItem then
                            for DataIndex = StartIndex, EndIndex do
                                local OptionData = VisibleOptions[DataIndex]

                                if OptionData and OptionData.Name == Dropdown.DragOption then
                                    Assignments[Dropdown.DragPoolItem] = {
                                        DataIndex = DataIndex,
                                        Option = OptionData,
                                    }
                                    UsedPoolItems[Dropdown.DragPoolItem] = true

                                    break
                                end
                            end
                        end

                        local PoolIndex = 1

                        for DataIndex = StartIndex, EndIndex do
                            local OptionData = VisibleOptions[DataIndex]

                            if not (Dropdown.DragStarted and OptionData and OptionData.Name == Dropdown.DragOption) then
                                while Dropdown.Pool[PoolIndex] and UsedPoolItems[Dropdown.Pool[PoolIndex] ] do
                                    PoolIndex = PoolIndex + 1
                                end

                                local PoolItem = Dropdown.Pool[PoolIndex]

                                if PoolItem then
                                    Assignments[PoolItem] = {
                                        DataIndex = DataIndex,
                                        Option = OptionData,
                                    }
                                    UsedPoolItems[PoolItem] = true
                                    PoolIndex = PoolIndex + 1
                                end
                            end
                        end

                        for _, PoolItem in Dropdown.Pool do
                            local Assignment = Assignments[PoolItem]

                            if Assignment then
