                                    PoolItem.EditText = PoolItem.Priority.Instance.Text

                                    PoolItem.Priority.Instance:ReleaseFocus(false)
                                end

                                PoolItem.Option = OptionData
                                PoolItem.Button.Instance.Visible = true
                                PoolItem.Button.Instance.Text = ''
                                PoolItem.Label.Instance.Text = Dropdown.Priority and StringFormat('%s. %s', tostring(OptionData.Priority or 0), OptionData.Name) or OptionData.Name
                                PoolItem.Button.Instance.Position = UDim2New(0, 0, 0, (DataIndex - 1) * Dropdown.OptionHeight)
                                PoolItem.Corner.Instance.CornerRadius = UDimNew(0, Dropdown.Priority and 4 or Library.LayoutTokens.ControlRadius)
                                PoolItem.Label.Instance.TextSize = Library.Typography.Body
                                PoolItem.Label.Instance.Position = Dropdown.Priority and UDim2New(0, 8, 0, 0) or UDim2New(0, 30, 0, 0)
                                PoolItem.Label.Instance.Size = Dropdown.Priority and UDim2New(1, 
-68, 1, 0) or UDim2New(1, -46, 1, 0)
                                PoolItem.CheckBox.Instance.Visible = not Dropdown.Priority
                                PoolItem.CheckBox.Instance.AnchorPoint = Vector2New(0, 0.5)
                                PoolItem.CheckBox.Instance.Position = UDim2New(0, 8, 0.5, 0)
                                PoolItem.Priority.Instance.Visible = Dropdown.Priority

                                if Dropdown.Priority and UserInputService:GetFocusedTextBox() ~= PoolItem.Priority.Instance then
                                    PoolItem.Priority.Instance.Text = tostring(OptionData.Priority or 0)
                                end

                                local OptionStroke = PoolItem.Button.Instance:FindFirstChildOfClass('UIStroke')

                                if Dropdown.Priority then
                                    local IsDragged = Dropdown.DragStarted and Dropdown.DragOption == OptionData.Name

                                    if IsDragged and Dropdown.DragVisualY then
                                        PoolItem.Button.Instance.Position = UDim2New(0, 0, 0, Dropdown.DragVisualY)
                                    end

                                    PoolItem.Button.Instance.ZIndex = IsDragged and 18 or 12
                                    PoolItem.Label.Instance.ZIndex = IsDragged and 19 or 13
                                    PoolItem.Priority.Instance.ZIndex = IsDragged and 20 or 14
                                    PoolItem.Button.Instance.BackgroundTransparency = IsDragged and 0.78 or 0
                                    PoolItem.Button.Instance.BackgroundColor3 = IsDragged and Library.Theme.Accent or Library.Theme['Sidebar Active']
                                    PoolItem.Label.Instance.TextColor3 = Library.Theme.Text
