                                    PoolItem.CheckBox.Instance.BackgroundTransparency = 1
                                    PoolItem.CheckBox.Instance.BackgroundColor3 = Library.Theme.Accent
                                    PoolItem.CheckStroke.Instance.Transparency = 1
