                    Dropdown:Layout()

                    function Dropdown:SetPriority(OptionName, Priority)
                        if Library.IsUnloading or Dropdown.Locked or not Dropdown.Priority then
                            return false
                        end

                        local OptionData = Dropdown.Options[OptionName]

                        Priority = MathFloor(tonumber(Priority) or 0)

                        if not OptionData or Priority < 1 then
                            Library:Toast({
                                Title = 'Priority must be at least 1',
                                Duration = 2.2,
                            })

                            return false
                        end

                        local PreviousPriority = Dropdown.Value[OptionData.Name]

                        if PreviousPriority == Priority then
                            Dropdown:RenderPool()

                            return true
                        end

                        local SwappedOption

                        for ExistingName, ExistingPriority in Dropdown.Value do
                            if ExistingName ~= OptionData.Name and tonumber(ExistingPriority) == Priority then
                                SwappedOption = Dropdown.Options[ExistingName]

                                break
                            end
                        end

                        local NextValues = TableClone(Dropdown.Value)

                        if SwappedOption then
                            NextValues[SwappedOption.Name] = PreviousPriority
                        end

                        NextValues[OptionData.Name] = Priority

                        Dropdown:Set(NextValues)

                        if SwappedOption then
                            Library:Toast({
                                Title = StringFormat('Swapped value - %s to %s', OptionData.Name, SwappedOption.Name),
                                Duration = 2.6,
                            })
                        end

                        return true, SwappedOption and SwappedOption.Name or nil
                    end
                    function Dropdown:Set(Option, Options)
                        if not (Options and Options.FromConfig) then
                            Library:CancelOptionCallback(Dropdown)
                        end
                        if Library.IsUnloading or not Dropdown.Section then
                            return false
                        end
                        if Dropdown.Priority then
                            if Option == nil then
                                Option = {}
                            end
                            if type(Option) ~= 'table' then
                                if Options and Options.FromConfig then
                                    Dropdown.ConfigRejected = Option
                                end

                                return false
                            end

                            local Sanitized = {}
                            local UsedPriorities = {}
                            local HighestPriority = 0
                            local HasInvalidOption = false

                            for Key, Value in Option do
                                local OptionName = type(Key) == 'number' and Value or Key
                                local Priority = type(Key) == 'number' and (#Option - Key + 1) or (Value == true and 1 or MathFloor(tonumber(Value) or 0))

                                if Dropdown.Options[OptionName] then
                                    if Priority > 0 and not UsedPriorities[Priority] then
                                        Sanitized[OptionName] = Priority
                                        UsedPriorities[Priority] = true
                                        HighestPriority = math.max(HighestPriority, Priority)
                                    else
                                        HasInvalidOption = true
                                    end
                                else
                                    HasInvalidOption = true
                                end
                            end

                            if HasInvalidOption and Options and Options.FromConfig then
                                Dropdown.ConfigRejected = TableClone(Option)

                                return false
                            end

                            Dropdown.ConfigRejected = nil

                            local MissingOptions = {}

                            for _, OptionData in Dropdown.OptionOrder do
                                if not Sanitized[OptionData.Name] then
                                    TableInsert(MissingOptions, OptionData.Name)
                                end
                            end

                            if #MissingOptions > 0 then
                                for OptionName, Priority in Sanitized do
                                    Sanitized[OptionName] = Priority + #MissingOptions
                                end
                                for Index, OptionName in MissingOptions do
                                    Sanitized[OptionName] = #MissingOptions - Index + 1
                                end
                            end

                            Dropdown.Value = TableClone(Sanitized)
                            Library.Flags[Dropdown.Flag] = TableClone(Dropdown.Value)

                            for _, OptionData in Dropdown.Options do
                                OptionData.Priority = Dropdown.Value[OptionData.Name] or 0
                                OptionData.Selected = true
                            end
                        elseif Dropdown.Multi then
                            if Option == nil then
                                Option = {}
                            end
                            if type(Option) ~= 'table' then
                                if Options and Options.FromConfig then
                                    Dropdown.ConfigRejected = Option
                                end

                                return false
                            end

                            local Sanitized = {}
                            local HasInvalidOption = false

                            for Key, Value in Option do
                                local OptionName = Value

                                if type(Key) == 'string' and Value == true then
                                    OptionName = Key
                                end
                                if Dropdown.Options[OptionName] and not TableFind(Sanitized, OptionName) then
                                    TableInsert(Sanitized, OptionName)
                                elseif not Dropdown.Options[OptionName] then
                                    HasInvalidOption = true
                                end
                            end

                            if HasInvalidOption and Options and Options.FromConfig then
                                Dropdown.ConfigRejected = TableClone(Option)

                                return false
