                        if not Alive() then
                            return false
                        end

                        local Update = type(Value) == 'table' and Value or {
                            Value = Value,
                            Change = Change,
                        }

                        if Update.Value ~= nil and type(Update.Value) ~= 'number' and type(Update.Value) ~= 'string' then
                            return false
                        end
                        if type(Update.Value) == 'number' and not History.Number(Update.Value) then
                            return false
                        end
                        if Update.Sample ~= nil and not History.Number(Update.Sample) then
                            return false
                        end
                        if Update.Time ~= nil and not History.Number(Update.Time) then
                            return false
                        end
                        if Update.Change ~= nil and Update.Change ~= false and not History.Number(Update.Change) then
                            return false
                        end
                        if Update.Status ~= nil then
                            local State = type(Update.Status) == 'table' and Update.Status.State or Update.Status

                            if not States[State] then
                                return false
                            end
                        end
                        if Update.Value ~= nil then
                            self.Value = Update.Value
                        end
                        if Update.Name ~= nil then
                            self.Name = tostring(Update.Name)
                        end
                        if Update.Prefix ~= nil then
                            self.Prefix = tostring(Update.Prefix)
                        end
                        if Update.Suffix ~= nil then
                            self.Suffix = tostring(Update.Suffix)
                        end
                        if Update.Change ~= nil then
                            self.Change = History.Number(Update.Change)
                        end
                        if Update.Status ~= nil then
                            UpdateStatus(Update.Status)
                        end

                        local Changed = false

                        if Update.Sample ~= nil or Update.Value ~= nil then
                            Changed = History.Append(Series, Update.Sample ~= nil and Update.Sample or Update.Value, Update.Time)
                        end

                        Render(Update.Value ~= nil, Changed)

                        return self
