                        end

                        local Chart = Items.Chart.Instance
                        local X = math.clamp((Input.Position.X - Chart.AbsolutePosition.X) / math.max(Chart.AbsoluteSize.X, 1), 0, 1)

                        Selected = math.floor(X * math.max(0, #Series.Samples - 1) + 0.5) + 1

                        Inspect()
                    end

                    Connect(Items.Chart.Instance.InputChanged, function(Input)
                        if Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch then
                            Select(Input)
                        end
                    end)
                    Connect(Items.Chart.Instance.InputBegan, function(Input)
                        if Input.UserInputType == Enum.UserInputType.Touch or Input.UserInputType == Enum.UserInputType.MouseButton1 then
                            Select(Input)
                        end
